<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
const props=defineProps<{career:any;busy:boolean}>()
const emit=defineEmits<{update:[value:any];error:[value:string];advance:[]}>()
const tab=ref('performance'), catalog=ref<any[]>([]), game=ref('dice'), percent=ref(1), quote=ref<any|null>(null)
const api='http://localhost:5098/api'
const activities:any={performance:[['training','Entrenamiento individual','€500 · atributo +2, energía −6'],['recovery','Fisioterapia y descanso','Gratis · energía +10, riesgo −6'],['nutrition','Nutrición','Coste salarial · energía +6'],['psychology','Psicología deportiva','Coste salarial · moral +8']],personal:[['social','Familia y amistades','€180 · moral +7, energía −2']],career:[['agent','Reunión con agente','€450 · fama y mercado'],['media','Media training','Coste salarial · medios +7']]}
const activityList=computed(()=>activities[tab.value]??[]), inventory=computed(()=>catalog.value.filter(x=>x.inventory>0))
async function call(path:string,body:any){const r=await fetch(api+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw new Error((await r.json()).error??'No se pudo completar la operación');return r.json()}
async function refresh(){try{catalog.value=await call('/career/shop/catalog',props.career);quote.value=await call('/career/casino/quote',{career:props.career,game:game.value,betPercent:percent.value})}catch(e){emit('error',e instanceof Error?e.message:'Error')}}
async function action(path:string,body:any){try{emit('update',await call(path,body));await refresh()}catch(e){emit('error',e instanceof Error?e.message:'Error')}}
const activity=(id:string)=>action('/career/activity',{career:props.career,activityId:id}),buy=(id:string)=>action('/career/shop',{career:props.career,productId:id}),open=()=>action('/career/casino/open',{career:props.career,game:game.value,betPercent:percent.value}),casino=(actionName:string)=>action('/career/casino/action',{career:props.career,action:actionName})
watch(()=>[props.career,game.value,percent.value],refresh,{deep:true});onMounted(refresh)
</script>
<template><section class="lifestyle-panel"><header><div><p class="eyebrow">VIDA FUERA DE CANCHA</p><h2>Tu pausa personal</h2></div><small v-if="career.activeEvent">El evento está pausado: puedes volver a él cuando quieras.</small><small v-else>Entre jornadas: el calendario no avanzará hasta que continúes.</small></header><nav><button v-for="x in [['performance','Rendimiento'],['personal','Vida personal'],['career','Carrera e imagen'],['shop','Tienda'],['casino','Casino']]" :key="x[0]" :class="{selected:tab===x[0]}" @click="tab=x[0]">{{x[1]}}</button></nav><div class="balance"><b>Saldo €{{career.player.money.toLocaleString('es-ES',{maximumFractionDigits:0})}}</b><span>Bienestar {{career.lifestyle?.wellbeing}} · Disciplina {{career.lifestyle?.discipline}}</span><span>Mantenimiento próximo €{{career.lifestyle?.recurringCostPerSeason??0}}</span></div><button v-if="!career.activeEvent&&!career.seasonComplete" class="continue" :disabled="busy" @click="emit('advance')">Continuar al siguiente evento o partido</button><div v-if="activityList.length" class="actions"><button v-for="x in activityList" :key="x[0]" :disabled="busy" @click="activity(x[0])"><b>{{x[1]}}</b><span>{{x[2]}}</span></button></div><div v-else-if="tab==='shop'" class="products"><article v-for="x in catalog" :key="x.id"><small>{{x.family}}</small><b>{{x.name}}</b><span>{{x.benefit}}</span><strong>€{{x.priceEur.toLocaleString('es-ES',{maximumFractionDigits:0})}}</strong><em v-if="x.maintenanceEur">+ €{{x.maintenanceEur.toLocaleString('es-ES',{maximumFractionDigits:0})}}/temporada</em><button :disabled="busy||!x.canBuy" @click="buy(x.id)">{{x.owned?'Comprado':x.inventory>=3?'Límite alcanzado':'Comprar'}}</button></article><article v-for="x in inventory" :key="'use-'+x.id"><small>INVENTARIO</small><b>Usar: {{x.name}}</b><span>{{x.inventory}} disponibles · caduca al cierre</span><button :disabled="busy" @click="activity('use:'+x.id)">Usar ahora</button></article></div><div v-else class="casino"><p><b>Casino ficticio</b> · saldo estrictamente interno, sin pagos ni equivalencia real.</p><template v-if="!career.casinoSession"><div class="casino-controls"><select v-model="game"><option value="dice">Dados</option><option value="roulette">Ruleta</option><option value="blackjack">Blackjack</option></select><button v-for="n in [1,2,4]" :key="n" :class="{selected:percent===n}" @click="percent=n">{{n}}% del saldo</button></div><div v-if="quote" class="quote"><b>Apuesta: €{{quote.betEur.toLocaleString('es-ES',{maximumFractionDigits:0})}}</b><span>Límite de pérdidas: €{{quote.sessionLossLimitEur.toLocaleString('es-ES',{maximumFractionDigits:0})}}</span><span>{{quote.payout}}</span><small v-if="quote.blockReason">{{quote.blockReason}}</small></div><button :disabled="busy||!quote?.canOpen" @click="open">Abrir mesa</button></template><template v-else><div class="quote"><b>{{career.casinoSession.game.toUpperCase()}} · mano {{career.casinoSession.handsPlayed}}/5</b><span>Apuesta actual €{{career.casinoSession.betEur}} · resultado sesión €{{career.casinoSession.netResult}}</span><span v-if="career.casinoSession.game==='blackjack'">Tu mano: {{career.casinoSession.playerCards.join(' + ')||'—'}} · Crupier: {{career.casinoSession.handInProgress?'?':'—'}}</span></div><div class="casino-controls"><button v-if="career.casinoSession.game==='dice'" @click="casino('high')">Alto (4–6)</button><button v-if="career.casinoSession.game==='dice'" @click="casino('low')">Bajo (1–3)</button><button v-if="career.casinoSession.game==='roulette'" @click="casino('red')">Rojo</button><button v-if="career.casinoSession.game==='roulette'" @click="casino('black')">Negro</button><button v-if="career.casinoSession.game==='roulette'" @click="casino('green')">Verde ×14</button><button v-if="career.casinoSession.game==='blackjack'&&!career.casinoSession.handInProgress" @click="casino('deal')">Repartir</button><button v-if="career.casinoSession.game==='blackjack'&&career.casinoSession.handInProgress" @click="casino('hit')">Pedir</button><button v-if="career.casinoSession.game==='blackjack'&&career.casinoSession.handInProgress" @click="casino('stand')">Plantarse</button><button v-if="career.casinoSession.game==='blackjack'&&career.casinoSession.handInProgress" @click="casino('double')">Doblar</button><button class="exit" @click="casino('exit')">Salir</button></div></template></div></section></template>
